import { describe, it, expect } from 'vitest';
import { createEngine } from '../../js/sim/engine.js';

// R2c pool truth (finding 1-06): the top-level primaryQueue / primaryFiles
// shape names the pool's primary backend's own story, and a write to the
// other backend lands only one level down — never in an aggregate.
describe('r2c pool truth — the snapshot schema names its primary backend', () => {
  it("the primary shape names itself — 'primaryQueue' / 'primaryFiles' - the pool's primary-backend story, not an aggregate", () => {
    const stage2 = createEngine({ seed: 42, stage: 2 });
    stage2.setWebFile('10.12', '/about', 'New body');
    const snap2 = stage2.snapshot();

    // The 10.12-side edit lands ONLY in servers[1].files — the primary
    // (10.11) view at the top level is unchanged, servers[0] too.
    expect(snap2.primaryFiles['/about']).toBe('This is the about page');
    expect(snap2.servers[1].files['/about']).toBe('New body');
    expect(snap2.servers[0].files['/about']).toBe('This is the about page');
    expect(Array.isArray(snap2.primaryQueue)).toBe(true);

    // One backend, one shape: at stage 1 the primary write IS the story.
    const stage1 = createEngine({ seed: 42, stage: 1 });
    stage1.setWebFile('10.1', '/about', 'New body');
    const snap1 = stage1.snapshot();
    expect(snap1.primaryFiles['/about']).toBe('New body');
    expect(snap1.servers[0].files['/about']).toBe('New body');
  });
});

